-- Creates the medical_codes reference table and seeds it with the
-- curated ICD-10 / SNOMED CT lists. From now on this table (not the
-- static JS files) is the live source for search/stats/admin-add.
CREATE TABLE IF NOT EXISTS medical_codes (
  id SERIAL PRIMARY KEY,
  system VARCHAR(10) NOT NULL CHECK (system IN ('icd','snomed')),
  code VARCHAR(20) NOT NULL,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  icd_link VARCHAR(20),
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(system, code)
);
CREATE INDEX IF NOT EXISTS idx_medical_codes_system ON medical_codes(system);
CREATE INDEX IF NOT EXISTS idx_medical_codes_search ON medical_codes USING GIN (to_tsvector('simple', name_ar || ' ' || name_en || ' ' || code));

